const input = $input.first().json;
const statusCode = input.statusCode ?? 200;
const body = input.body ?? input;
if (statusCode >= 400) return [{ json: { statusCode, response: body } }];
if (!body.request_id || !body.report_markdown || !body.follow_up_draft) throw new Error('HeatBrief response is missing briefing evidence');
return [{ json: { statusCode, response: { ...body, review_required: body.status === 'draft_pending_review', human_review: 'Read the evidence, report and draft. A human may record a decision using the separate review API token. No message is sent.' } } }];
